-- Compte SQL de l'application, exemple VULNERABLE
CREATE USER 'appuser'@'%' IDENTIFIED BY 'motdepasse';
GRANT ALL PRIVILEGES ON *.* TO 'appuser'@'%' WITH GRANT OPTION;
FLUSH PRIVILEGES;

